@isTest private class CurrentBaseEventBusChangeEventHeaderTest {
 @isTest static void documentedFieldsRoundTripWitness() {
  EventBus.ChangeEventHeader header = new EventBus.ChangeEventHeader();
  header.changeorigin = 'com.salesforce.api';
  header.changetype = 'UPDATE';
  header.commitnumber = 42L;
  header.committimestamp = 123456789L;
  header.commituser = '005000000000001AAA';
  header.difffields = new List<String>{'Description'};
  header.entityname = 'Account';
  header.nulledfields = new List<String>();
  header.recordids = new List<String>{'001000000000001AAA'};
  header.sequencenumber = 7;
  header.transactionkey = 'txn-20260807';
  System.assertEquals('com.salesforce.api', header.changeorigin);
  System.assertEquals('UPDATE', header.changetype);
  System.assertEquals(42L, header.commitnumber);
  System.assertEquals(123456789L, header.committimestamp);
  System.assertEquals('005000000000001AAA', header.commituser);
  System.assertEquals('Description', header.difffields[0]);
  System.assertEquals('Account', header.entityname);
  System.assertEquals(0, header.nulledfields.size());
  System.assertEquals('001000000000001AAA', header.recordids[0]);
  System.assertEquals(7, header.sequencenumber);
  System.assertEquals('txn-20260807', header.transactionkey);
 }
}
